-- mod-temucraft-class-tweaks: Overloaded Blast (mage), Elune's Arrow (night elf priest), Stonewall Slam (shaman).
-- The client has the same rows in Spell.dbc. Made by tools/build_new_spells.py.
SET @NewSpell := 100110;
DELETE FROM `spell_dbc` WHERE `ID` BETWEEN @NewSpell AND @NewSpell+16;
DELETE FROM `spell_dbc` WHERE `ID` IN (@NewSpell, @NewSpell+1, @NewSpell+2, @NewSpell+3, @NewSpell+4, @NewSpell+5, @NewSpell+6, @NewSpell+7, @NewSpell+8, @NewSpell+9, @NewSpell+10, @NewSpell+11, @NewSpell+12, @NewSpell+13, @NewSpell+14, @NewSpell+15, @NewSpell+16);

DELETE FROM `spell_ranks` WHERE `first_spell_id` IN (@NewSpell, @NewSpell+9);
DELETE FROM `spell_bonus_data` WHERE `entry` IN (@NewSpell, @NewSpell+9);
DELETE FROM `spell_proc` WHERE `SpellId` = @NewSpell+8;
DELETE FROM `spell_script_names` WHERE `spell_id` = @NewSpell+8;
